<template><div class="evidence-graph"><v-alert v-if="graph.truncated" type="warning" variant="tonal" density="compact" class="mb-4">Graph traversal reached its safety cap. The visible relationships are complete only within this bounded result.</v-alert><div class="graph-canvas" role="img" :aria-label="`Directed dependency graph with ${graph.resources.length} resources and ${graph.relations.length} relationships`"><div v-for="relation in graph.relations" :key="`${relation.from}-${relation.to}-${relation.type}`" class="edge" data-edge><div class="node"><span>{{ resource(relation.from)?.provenance.kind || 'Unknown' }}</span><strong>{{ resource(relation.from)?.provenance.name || relation.from }}</strong></div><div class="arrow"><v-chip size="x-small" variant="tonal">{{ relation.type }}</v-chip><span aria-hidden="true">→</span><small>{{ relation.evidence }} · {{ relation.confidence }}</small></div><div class="node"><span>{{ resource(relation.to)?.provenance.kind || 'Unknown' }}</span><strong>{{ resource(relation.to)?.provenance.name || relation.to }}</strong></div></div><p v-if="!graph.relations.length" class="empty">No directed relationships were returned by the graph API.</p></div><details class="fallback" open><summary>Accessible relationship table</summary><TopologyRelations :graph="graph" :root-key="rootKey"/></details></div></template>
<script setup lang="ts">
import type { SreGraph } from '@/api/sre'
import TopologyRelations from './TopologyRelations.vue'
const props=defineProps<{ graph:SreGraph; rootKey:string }>()
const resource=(key:string)=>props.graph.resources.find(item=>item.key===key)
</script>
<style scoped>.graph-canvas{display:flex;flex-direction:column;gap:12px;padding:16px;border:1px solid var(--ic-border);border-radius:10px;background:var(--ic-canvas)}.edge{display:grid;grid-template-columns:minmax(140px,1fr) minmax(150px,.8fr) minmax(140px,1fr);align-items:center;gap:12px}.node{display:flex;flex-direction:column;padding:11px;border:1px solid var(--ic-border);border-radius:8px;background:var(--ic-surface);min-width:0}.node span,.arrow small{color:var(--ic-text-muted);font-size:10px;text-transform:uppercase}.node strong{overflow-wrap:anywhere}.arrow{display:grid;justify-items:center;gap:3px}.arrow>span{font-size:20px}.fallback{margin-top:16px}.fallback summary{cursor:pointer;font-weight:600;margin-bottom:10px}.empty{color:var(--ic-text-muted)}@media(max-width:650px){.edge{grid-template-columns:1fr}.arrow>span{transform:rotate(90deg)}}</style>
